  const n=800,tone=new Float32Array(n);for(let i=0;i<n;i++)tone[i]=Math.sin(2*Math.PI*770*i/sr)+Math.sin(2*Math.PI*1336*i/sr);const lo=[697,770,852,941].map(f=>goertzel(tone,f,sr)),hi=[1209,1336,1477].map(f=>goertzel(tone,f,sr));
