function dijkstra(n,E,a){const d=Array(n).fill(1e9),p=Array(n).fill(-1),u=Array(n).fill(0);d[a]=0;for(let k=0;k<n;k++){let m=-1;for(let i=0;i<n;i++)if(!u[i]&&(m<0||d[i]<d[m]))m=i;u[m]=1;E.forEach(([x,y,w])=>{for(const[s,t]of[[x,y],[y,x]])if(s===m&&d[m]+w<d[t]){d[t]=d[m]+w;p[t]=m}})}return{d,p}}
