function hparse(s){const root={tag:'root',kids:[]},st=[root];const re=/<(\/?)(\w+)([^>]*)>|([^<]+)/g;let m;while((m=re.exec(s))){if(m[4]){const t=m[4].replace(/\s+/g,' ');if(t.trim())st[st.length-1].kids.push({tag:'#text',text:t})}else if(m[1]){const i=st.map(n=>n.tag).lastIndexOf(m[2].toLowerCase());if(i>0)st.length=i}
 else{const tag=m[2].toLowerCase(),at={};(m[3].match(/(\w+)="([^"]*)"/g)||[]).forEach(a=>{const k=a.split('=')[0];at[k]=a.slice(k.length+2,-1)});const n={tag,at,kids:[]};st[st.length-1].kids.push(n);if(!['img','br'].includes(tag))st.push(n)}}return root}
function sig(n){return n.tag==='#text'?'t':n.tag+(n.kids&&n.kids.length?'('+n.kids.map(sig).join(',')+')':'')}
