function usenetSim(seed,steps,sept){const r=rng(seed),P=[{id:0,p:-1,t:0,d:0,newbie:0}];for(let s=1;s<=steps;s++){const rate=sept&&s>steps/3?4:1;for(let k=0;k<rate;k++){const nb=sept&&s>steps/3&&r()<.7;const par=r()<.25?-1:(r()*P.length)|0;P.push({id:P.length,p:par,t:s,d:par<0?0:P[par].d+1,newbie:nb?1:0})}}return P}
